export interface SendNotificationPayload {
  tokens: string[];
  title: string;
  body: string;
  imageUrl?: string;
  actionUrl?: string;
  data?: Record<string, string>;
}

export async function sendFCMNotification(payload: SendNotificationPayload): Promise<{
  successCount: number;
  failureCount: number;
  errors?: string[];
}> {
  const { tokens, title, body, imageUrl, actionUrl, data } = payload;

  if (tokens.length === 0) {
    return { successCount: 0, failureCount: 0 };
  }

  // Initialize Firebase Admin
  const app = initializeFirebaseAdmin();
  const messaging = admin.messaging(app);

  let successCount = 0;
  let failureCount = 0;
  const errors: string[] = [];

  // Firebase Admin SDK supports sending to multiple tokens at once
  const message: admin.messaging.MulticastMessage = {
    tokens,
    notification: {
      title,
      body,
      ...(imageUrl && { imageUrl }),
    },
    data: {
      ...(data || {}),
      ...(actionUrl && { actionUrl }),
      title: title, // Tambahkan title di data untuk foreground handling
      body: body,   // Tambahkan body di data untuk foreground handling
    },
    webpush: {
      headers: {
        TTL: '86400', // 24 jam sesuai dokumentasi
        Urgency: 'high',
      },
      notification: {
        icon: '/icons/pwa-192x192.png',
        badge: '/icons/pwa-192x192.png',
        requireInteraction: true,
        ...(imageUrl && { image: imageUrl }),
      },
      fcmOptions: {
        link: actionUrl || '/',
      },
    },
  };

  try {
    const response = await messaging.sendEachForMulticast(message);

    successCount = response.successCount;
    failureCount = response.failureCount;

    // Collect error details
    response.responses.forEach((resp, idx) => {
      if (!resp.success && resp.error) {
        errors.push(`Token ${idx}: ${resp.error.message}`);
      }
    });

    console.log(`✅ Sent to ${successCount} devices, failed: ${failureCount}`);
  } catch (error: any) {
    console.error('Error sending FCM notification:', error);
    failureCount = tokens.length;
    errors.push(error.message);
  }

  return {
    successCount,
    failureCount,
    ...(errors.length > 0 && { errors }),
  };
}

